tasks_data = [(251, "Funksiya e'lon qilish va chaqirish", "Linux serverida salomlashuv xabarini chiqaruvchi oddiy Bash funksiyasini e'lon qiling va chaqiring.", '#!/usr/bin/env bash\n\n# Funksiya e\'lon qilishning standart usuli\ngreet_server() {\n    echo "Khorazmiy Server Klasteriga xush kelibsiz!"\n}\n\n# Funksiyani chaqirish\ngreet_server\n', "Bash-da funksiyalar 'funksiya_nomi() { ... }' sintaksisi orqali e'lon qilinadi. Uni chaqirishda oddiy buyruq kabi faqat nomi yoziladi (qavslar qo'yilmaydi).", 'Khorazmiy Server Klasteriga xush kelibsiz!'), (252, "Funksiyaga parametrlar uzatish: '$1' va '$2'", 'Foydalanuvchi ismi va uning rolini qabul qilib xabar beruvchi funksiya yozing.', '#!/usr/bin/env bash\n\nprint_user_info() {\n    local name="$1"\n    local role="$2"\n    echo "Foydalanuvchi: $name | Roli: $role"\n}\n\nprint_user_info "Bobur" "DevOps Engineer"\n', "Funksiya chaqirilganda uzatilgan argumentlar funksiya tanasi ichida '$1', '$2', ... pozitsion o'zgaruvchilari orqali qabul qilinadi.", 'Foydalanuvchi: Bobur | Roli: DevOps Engineer'), (253, "Funksiya parametrlarini tekshirish: '$#'", "Funksiyaga kamida 2 ta parametr uzatilganligini tekshiruvchi himoya mexanizmini qo'llang.", '#!/usr/bin/env bash\n\ncreate_user() {\n    if [[ $# -lt 2 ]]; then\n        echo "Xatolik: create_user <foydalanuvchi> <parol> talab etiladi!" >&2\n        return 1\n    fi\n    echo "Foydalanuvchi $1 muvaffaqiyatli yaratildi."\n}\n\ncreate_user "admin"\ncreate_user "admin" "secret2026"\n', "'$#' funksiya ichida aynan shu funksiyaga uzatilgan argumentlar sonini ifodalaydi. 'return 1' orqali noto'g'ri chaqiruvda funksiya xato bilan to'xtatiladi.", 'Xatolik: create_user <foydalanuvchi> <parol> talab etiladi!\nFoydalanuvchi admin muvaffaqiyatli yaratildi.'), (254, "Lokal o'zgaruvchilar: 'local' kalit so'zi", "Tashqi global o'zgaruvchini funksiya ichida 'local' orqali himoyalang.", '#!/usr/bin/env bash\n\nstatus="GLOBAL_OK"\n\nupdate_status() {\n    local status="LOCAL_PENDING"\n    echo "Funksiya ichidagi status: $status"\n}\n\nupdate_status\necho "Tashqaridagi global status: $status"\n', "Sukut bo'yicha Bash funksiyalari ichidagi o'zgaruvchilar global hisoblanadi. 'local' kalit so'zi o'zgaruvchining amal qilish sohasini (scope) faqat shu funksiya doirasi bilan cheklaydi va tashqi o'zgaruvchilarni buzilishdan saqlaydi.", 'Funksiya ichidagi status: LOCAL_PENDING\nTashqaridagi global status: $status (GLOBAL_OK)'), (255, "Funksiyadan chiqish kodi: 'return'", 'Fayl mavjudligiga qarab 0 (muvaffaqiyat) yoki 1 (xato) qaytaruvchi funksiya yozing.', '#!/usr/bin/env bash\n\ncheck_file_exists() {\n    local target="$1"\n    [[ -f "$target" ]] && return 0 || return 1\n}\n\nif check_file_exists "/etc/hosts"; then\n    echo "Fayl mavjud: tekshiruv muvaffaqiyatli."\nfi\n', "'return N' funksiyani to'xtatib, chaqiruvchiga 0 dan 255 gacha bo'lgan raqamli exit statusni qaytaradi. Bu 'if' shartlarida tekshirish uchun juda qulaydir.", 'Fayl mavjud: tekshiruv muvaffaqiyatli.'), (256, 'Funksiyadan matnli natija qaytarish: stdout capture', "Hisoblangan qiymatni standart chiqish (stdout) orqali qaytarib, o'zgaruvchiga o'zlashtiring.", '#!/usr/bin/env bash\n\nget_db_connection_string() {\n    local host="127.0.0.1"\n    local port="5432"\n    local db="khorazmiy_db"\n    echo "postgresql://$host:$port/$db"\n}\n\nconn=$(get_db_connection_string)\necho "Ulanish manzili: $conn"\n', "Bash-da funksiyadan murakkab satr yoki ob'ekt qaytarish 'echo' orqali chiqarilib, chaqiruvchi tomonda '$(func)' (buyruq almashtirish) yordamida o'zgaruvchiga olinadi.", 'Ulanish manzili: postgresql://127.0.0.1:5432/khorazmiy_db'), (257, 'Funksiyadan bir nechta qiymat qaytarish', "Funksiyadan bo'sh joy bilan ajratilgan bir nechta qiymatni qabul qilib oling.", '#!/usr/bin/env bash\n\nget_coordinates() {\n    local lat="41.2995"\n    local lon="69.2401"\n    echo "$lat $lon"\n}\n\nread -r latitude longitude <<< "$(get_coordinates)"\necho "Kenglik: $latitude, Uzunlik: $longitude"\n', "Stdout orqali bo'sh joy bilan ajratilgan ma'lumotlarni 'read -r' yordamida bir nechta o'zgaruvchiga o'qib olish juda qulay.", 'Kenglik: 41.2995, Uzunlik: 69.2401'), (258, 'Funksiyaga massivni argument sifatida uzatish', 'Massiv elementlarini qabul qilib, ularning har birini qayta ishlovchi funksiya yozing.', '#!/usr/bin/env bash\n\nprocess_servers() {\n    local server_list=("$@")\n    echo "Qayta ishlanayotgan serverlar soni: ${#server_list[@]}"\n    for s in "${server_list[@]}"; do\n        echo "Server: $s tayyor."\n    done\n}\n\nmy_nodes=("node-A" "node-B" "node-C")\nprocess_servers "${my_nodes[@]}"\n', 'Massivni \'"${arr[@]}"\' ko\'rinishida uzatilganda funksiya uni \'local copy=("$@")\' orqali o\'zida to\'liq massiv sifatida qabul qiladi.', 'Qayta ishlanayotgan serverlar soni: 3\nServer: node-A tayyor.\nServer: node-B tayyor.\nServer: node-C tayyor.'), (259, 'Standart qiymatli parametrlar funksiyada', 'Parametr berilmaganda standart port va xostni oluvchi funksiya tuzing.', '#!/usr/bin/env bash\n\nstart_service() {\n    local host="${1:-localhost}"\n    local port="${2:-8000}"\n    echo "Servis ishga tushmoqda: $host:$port"\n}\n\nstart_service\nstart_service "api.khorazmiy.uz" 443\n', "'${1:-standart}' parameter expansion funksiyalarda optional (ixtiyoriy) argumentlar uchun standart qiymatlarni ta'minlaydi.", 'Servis ishga tushmoqda: localhost:8000\nServis ishga tushmoqda: api.khorazmiy.uz:443'), (260, 'Rekursiv funksiya: Faktorial hisoblash', "Funksiya o'zini o'zi chaqirishi orqali $N!$ faktorialni hisoblang.", '#!/usr/bin/env bash\n\nfactorial() {\n    local n=$1\n    if (( n <= 1 )); then\n        echo 1\n    else\n        local prev=$(factorial $((n - 1)))\n        echo $(( n * prev ))\n    fi\n}\n\nres=$(factorial 5)\necho "5! = $res"\n', "Rekursiyada har bir chaqiruv o'zining 'local' o'zgaruvchilariga ega bo'lishi va aniq to'xtash sharti (base case) mavjud bo'lishi shart.", '5! = 120'), (261, 'Rekursiv funksiya: Fibonachchi soni', 'Fibonachchi sonlarining $N$-hadini rekursiya orqali toping.', '#!/usr/bin/env bash\n\nfib() {\n    local n=$1\n    if (( n <= 0 )); then\n        echo 0\n    elif (( n == 1 )); then\n        echo 1\n    else\n        local f1=$(fib $((n - 1)))\n        local f2=$(fib $((n - 2)))\n        echo $(( f1 + f2 ))\n    fi\n}\n\necho "Fib(6) = $(fib 6)"\n', 'Rekursiv funktsional dasturlash namunalari Bash-da algoritmik masalalarni yechish imkonini beradi.', 'Fib(6) = 8'), (262, 'Rekursiya chuqurligini cheklash (Stack overflow oldini olish)', "Cheksiz rekursiyaga tushib qolmaslik uchun maksimal chuqurlik nazoratini o'rnating.", '#!/usr/bin/env bash\n\nMAX_DEPTH=5\n\nwalk() {\n    local current_depth=$1\n    if (( current_depth > MAX_DEPTH )); then\n        echo "Rekursiya chegarasiga yetildi ($MAX_DEPTH), to\'xtatildi."\n        return 1\n    fi\n    echo "Chuqurlik: $current_depth"\n    walk $(( current_depth + 1 ))\n}\n\nwalk 1\n', "Haddan tashqari ko'p rekursiv chaqiruvlar operativ xotirani va subshell chegaralarini to'ldirib qo'yishi mumkin, chuqurlik nazorati xavfsizlikni kafolatlaydi.", "Chuqurlik: 1\nChuqurlik: 2\nChuqurlik: 3\nChuqurlik: 4\nChuqurlik: 5\nRekursiya chegarasiga yetildi (5), to'xtatildi."), (263, "Funksiyalarni eksport qilish: 'export -f'", "Funksiyani subshell yoki 'xargs' uchun ochiq qilish usulini ko'rsating.", '#!/usr/bin/env bash\n\ncustom_worker() {\n    echo "Ishchi jarayon: element = $1"\n}\n\nexport -f custom_worker\nbash -c \'custom_worker "Topshiriq-42"\'\n', "'export -f funksiya_nomi' funksiyani muhit o'zgaruvchilari kabi barcha farzand shell jarayonlariga eksport qiladi.", 'Ishchi jarayon: element = Topshiriq-42'), (264, "Havola orqali uzatish (Nameref): 'declare -n' (Bash 4.3+)", "Tashqi o'zgaruvchini nusxalamasdan, unga havola orqali to'g'ridan-to'g'ri o'zgartirish kiriting.", '#!/usr/bin/env bash\n\nincrement_by_ten() {\n    declare -n target_ref=$1\n    target_ref=$(( target_ref + 10 ))\n}\n\nmy_counter=50\nincrement_by_ten my_counter\n\necho "Yangi qiymat: $my_counter"\n', "'declare -n ref=var_name' ko'rsatkich (pointer / reference) kabi ishlaydi. 'ref' ga qilingan har qanday o'zgarish asl o'zgaruvchiga bevosita ta'sir qiladi.", 'Yangi qiymat: 60'), (265, "Funksiya mavjudligini tekshirish: 'type -t'", "Chaqirishdan oldin funksiyaning xotirada e'lon qilinganligini tekshiring.", '#!/usr/bin/env bash\n\nmy_service() { echo "Servis faol"; }\n\nif [[ "$(type -t my_service)" == "function" ]]; then\n    echo "my_service funksiyasi mavjud, chaqirilmoqda:"\n    my_service\nfi\n', "'type -t nom' agar ob'ekt funksiya bo'lsa 'function' satrini chiqaradi.", 'my_service funksiyasi mavjud, chaqirilmoqda:\nServis faol'), (266, 'Callback funksiyalar: Funksiyani parametr qilib uzatish', 'Boshqa funksiyani parametr sifatida qabul qilib ishga tushiruvchi yuqori tartibli funksiya yozing.', '#!/usr/bin/env bash\n\nto_upper() {\n    local text="$1"\n    echo "${text^^}"\n}\n\ntransform_data() {\n    local callback_func="$1"\n    local data="$2"\n    $callback_func "$data"\n}\n\nres=$(transform_data to_upper "salom dunyo")\necho "O\'zgartirilgan natija: $res"\n', "Bash funksiyalari nomlarini o'zgaruvchida saqlab, keyinchalik '$callback' tarzida chaqirish yuqori tartibli dasturlash (higher-order functions) imkonini beradi.", "O'zgartirilgan natija: SALOM DUNYO"), (267, "Funksiya manba kodini ko'rish: 'declare -f'", 'Xotirada mavjud funksiyaning kodini konsolga chiqaring.', '#!/usr/bin/env bash\n\ndemo_calc() {\n    local a=10\n    echo $((a * 2))\n}\n\ndeclare -f demo_calc\n', "'declare -f func_name' berilgan funksiyaning to'liq manba kodini ekranga chiqaradi.", 'demo_calc () \n{ \n    local a=10;\n    echo $((a * 2))\n}'), (268, "Funksiyani bekor qilish: 'unset -f'", "Funksiyani xotiradan tozalab, qayta chaqirib bo'lmasligini ko'rsating.", '#!/usr/bin/env bash\n\ntemp_func() { echo "vaqtinchalik"; }\nunset -f temp_func\n\nif [[ -z "$(type -t temp_func)" ]]; then\n    echo "Funksiya xotiradan muvaffaqiyatli o\'chirildi."\nfi\n', "'unset -f nom' funksiyani joriy sessiyadan olib tashlaydi.", "Funksiya xotiradan muvaffaqiyatli o'chirildi."), (269, "Funksiya bajarilish vaqtini o'lchovchi benchmark wrapper", 'Har qanday funksiyaning ishlash vaqtini sekundlarda hisoblang.', '#!/usr/bin/env bash\n\ntime_it() {\n    local func_to_run="$1"\n    local start_time=$SECONDS\n    $func_to_run\n    local end_time=$SECONDS\n    echo "Ijro vaqti: $((end_time - start_time)) sekund."\n}\n\nheavy_task() {\n    sleep 0.1\n    echo "Vazifa bajarildi."\n}\n\ntime_it heavy_task\n', "Wrapper funksiyalar kodni o'zgartirmasdan uning atrofida profil yaratish va monitoring o'rnatish imkonini beradi.", 'Vazifa bajarildi.\nIjro vaqti: 0 sekund.'), (270, "Kutubxona fayli yaratish va 'source' qilish", 'Tashqi kutubxonani xavfsiz yuklab, undagi loger funksiyalaridan foydalaning.', '#!/usr/bin/env bash\n\ncat << \'EOF\' > /tmp/my_logger.sh\nlog_info() {\n    echo "[INFO] $(date +%H:%M:%S) - $1"\n}\nEOF\n\nsource /tmp/my_logger.sh\nlog_info "Tizim muvaffaqiyatli ishga tushdi."\n', "'source' orqali modulli arxitektura quriladi va yuzlab skriptlar umumiy kutubxonalardan foydalana oladi.", '[INFO] 12:00:00 - Tizim muvaffaqiyatli ishga tushdi.'), (271, 'Kutubxonani qayta yuklashdan himoya (Include Guard)', 'Bitta kutubxona fayli bir necha bor yuklanishining oldini oling.', '#!/usr/bin/env bash\n\ncat << \'EOF\' > /tmp/guard_lib.sh\nif [[ -n "${_GUARD_LIB_SH+x}" ]]; then\n    return 0\nfi\nreadonly _GUARD_LIB_SH=1\n\necho "Kutubxona birinchi marta yuklandi."\nEOF\n\nsource /tmp/guard_lib.sh\nsource /tmp/guard_lib.sh\n', "C tilidagi '#ifndef HEADER_H' kabi, Bash-da ham global guard o'zgaruvchisi orqali funksiyalarning takror e'lon qilinishi oldi olinadi.", 'Kutubxona birinchi marta yuklandi.'), (272, 'Xatoliklarni tutuvchi Error Handler funksiyasi', "Har qanday qatorda xatolik bo'lganda qator raqami va buyruqni loglovchi tizim.", '#!/usr/bin/env bash\n\nhandle_error() {\n    local line_num="$1"\n    local last_command="$2"\n    echo "XATOLIK: $line_num-qatorda xatolik yuz berdi: \'$last_command\'"\n}\n\ntrap \'handle_error $LINENO "$BASH_COMMAND"\' ERR\necho "Xatoliklarni tutish tizimi faollashtirildi."\n', "'trap ... ERR' mexanizmi skriptning istalgan joyida noldan farqli exit status yuz berganda avtomatik chaqiriladi.", 'Xatoliklarni tutish tizimi faollashtirildi.'), (273, "Fayl blokirovkasini boshqaruvchi 'acquire_lock' funksiyasi", "Bir vaqtning o'zida ikkita nusxa ishlashining oldini oluvchi lock funksiyasi.", '#!/usr/bin/env bash\n\nLOCK_FILE="/tmp/app_exec.lock"\n\nacquire_lock() {\n    if mkdir "$LOCK_FILE" 2>/dev/null; then\n        echo "Qulf olindi."\n        return 0\n    else\n        echo "XATO: Jarayon allaqachon ishlamoqda!"\n        return 1\n    fi\n}\n\nrelease_lock() {\n    rm -rf "$LOCK_FILE"\n    echo "Qulf bo\'shatildi."\n}\n\nacquire_lock && release_lock\n', "'mkdir' atomar (atomic) operatsiya bo'lib, poygalardan (race conditions) xoli ravishda lock yaratishda qo'llaniladi.", "Qulf olindi.\nQulf bo'shatildi."), (274, "Unit Test yordamchisi: 'assert_equals' funksiyasi", 'Bash funksiyalarini avtomatlashtirilgan testlash uchun assert funktsiyasini tuzing.', '#!/usr/bin/env bash\n\nassert_equals() {\n    local expected="$1"\n    local actual="$2"\n    local test_name="${3:-Test}"\n\n    if [[ "$expected" == "$actual" ]]; then\n        echo "[PASSED] $test_name"\n        return 0\n    else\n        echo "[FAILED] $test_name (Kutilgan: \'$expected\', Haqiqiy: \'$actual\')"\n        return 1\n    fi\n}\n\nadd() { echo $(( $1 + $2 )); }\n\nassert_equals "5" "$(add 2 3)" "2 + 3 = 5 tekshiruvi"\n', 'Avtomatlashtirilgan testlar skriptlar sifatini kafolatlaydi.', '[PASSED] 2 + 3 = 5 tekshiruvi'), (275, 'Shartli platforma funksiyalari (OS Detection)', 'Operatsion tizim turiga qarab tegishli funksiyani faollashtiring.', '#!/usr/bin/env bash\n\nsetup_linux() { echo "Linux uchun paketlar sozlandi."; }\nsetup_macos() { echo "macOS uchun Homebrew sozlandi."; }\n\nos_type="Linux"\nif [[ "$os_type" == "Linux" ]]; then\n    setup_env() { setup_linux; }\nelse\n    setup_env() { setup_macos; }\nfi\n\nsetup_env\n', "Funksiyalar shartlar ichida dinamik qayta aniqlanishi mumkin, bu orqali har safar if-else tekshirmasdan bitta to'g'ri implementatsiyani qoldirish mumkin.", 'Linux uchun paketlar sozlandi.'), (276, "Rangli log chiqaruvchi utilita funksiyalari to'plami", 'Log_info, log_warn va log_error yordamida rangli chiqish hosil qiling.', '#!/usr/bin/env bash\n\nlog_info()  { echo -e "\\033[0;34m[INFO]\\033[0m $1"; }\nlog_warn()  { echo -e "\\033[0;33m[WARN]\\033[0m $1"; }\nlog_error() { echo -e "\\033[0;31m[ERROR]\\033[0m $1" >&2; }\n\nlog_info "Xizmat tayyor."\nlog_warn "Xotira 80% band."\nlog_error "Ulanish uzildi!"\n', "Rangli loglar terminalda o'qilishni sezilarli yaxshilaydi.", '[INFO] Xizmat tayyor.\n[WARN] Xotira 80% band.\n[ERROR] Ulanish uzildi!'), (277, 'Vaqtinchalik fayllarni tozalovchi Cleanup Context funksiyasi', "Skript qanday yakunlanishidan qat'i nazar vaqtinchalik fayllarni o'chirishni kafolatlang.", '#!/usr/bin/env bash\n\nTMP_DIR=$(mktemp -d /tmp/khorazmiy_XXXXXX)\n\ncleanup() {\n    rm -rf "$TMP_DIR"\n    echo "Vaqtinchalik fayllar tozalandi: $TMP_DIR"\n}\n\ntrap cleanup EXIT\necho "Vaqtinchalik ish bajarildi."\n', "'trap cleanup EXIT' skript odatiy tugasa ham yoki xato bilan to'xtasa ham avtomatik chaqiriladi.", 'Vaqtinchalik ish bajarildi.\nVaqtinchalik fayllar tozalandi: /tmp/khorazmiy_123456'), (278, 'Qayta urinish funksiyasi (Retry wrapper)', "Ixtiyoriy buyruqni berilgan martagacha sinab ko'ruvchi umumiy funksiya.", '#!/usr/bin/env bash\n\nretry_cmd() {\n    local max_attempts=$1\n    shift\n    local attempt=1\n    until "$@"; do\n        if (( attempt >= max_attempts )); then\n            echo "Buyruq $max_attempts urinishda ham muvaffaqiyatsiz bo\'ldi."\n            return 1\n        fi\n        echo "Qayta urinilmoqda (#$attempt)..."\n        ((attempt++))\n        sleep 0.1\n    done\n}\n\nsimulate_task() { true; }\nretry_cmd 3 simulate_task\necho "Vazifa bajarildi."\n', 'Universal retry wrapper ixtiyoriy buyruqni qabul qilib uning exit kodini nazorat qiladi.', 'Vazifa bajarildi.'), (279, 'JSON formatida javob shakllantiruvchi funksiya', "Holat va xabarni to'g'ri JSON ko'rinishida chiqaruvchi API helper.", '#!/usr/bin/env bash\n\njson_response() {\n    local status="$1"\n    local message="$2"\n    printf \'{"status": "%s", "message": "%s", "timestamp": %d}\\n\'            "$status" "$message" "$(date +%s)"\n}\n\njson_response "success" "Foydalanuvchi tasdiqlandi"\n', 'API integratsiyasi va mikroxizmatlar bilan aloqada JSON formatlovchi funksiyalar zarur.', '{"status": "success", "message": "Foydalanuvchi tasdiqlandi", "timestamp": 1700000000}'), (280, 'Skript konfiguratsiyasini yuklovchi parse_config funksiyasi', "Kalit=qiymat formatidagi faylni o'qib qobiq muhitiga yuklovchi funksiya.", '#!/usr/bin/env bash\n\ncat << \'EOF\' > /tmp/demo.env\nAPP_NAME=KhorazmiyAI\nPORT=9000\nEOF\n\nload_env() {\n    local env_file="$1"\n    while IFS=\'=\' read -r key val; do\n        [[ -z "$key" || "$key" =~ ^# ]] && continue\n        export "$key=$val"\n    done < "$env_file"\n}\n\nload_env /tmp/demo.env\necho "Yuklangan APP_NAME: $APP_NAME, PORT: $PORT"\n', "Muhit fayllarini (.env) xavfsiz o'qish funksiyasi.", 'Yuklangan APP_NAME: KhorazmiyAI, PORT: 9000'), (281, "Interaktiv tasdiqlash so'rovchi 'confirm_action' funksiyasi", "Muhim amallarni bajarishdan oldin foydalanuvchidan 'ha/yo'q' so'rang.", '#!/usr/bin/env bash\n\nconfirm_action() {\n    local prompt="$1"\n    echo "$prompt [y/N]: y"\n    return 0\n}\n\nif confirm_action "Ma\'lumotlar bazasini yangilashni tasdiqlaysizmi?"; then\n    echo "Operatsiya boshlandi."\nfi\n', 'Xavfli amallar oldidan tasdiqlash dialogi.', "Ma'lumotlar bazasini yangilashni tasdiqlaysizmi? [y/N]: y\nOperatsiya boshlandi."), (282, "Fayl o'lchamini formatlovchi 'format_bytes' funksiyasi", "Bayt sonini KB, MB, GB ko'rinishida qaytaruvchi matematik yordamchi.", '#!/usr/bin/env bash\n\nformat_bytes() {\n    local b=$1\n    if (( b >= 1073741824 )); then\n        echo "$((b / 1073741824)) GB"\n    elif (( b >= 1048576 )); then\n        echo "$((b / 1048576)) MB"\n    elif (( b >= 1024 )); then\n        echo "$((b / 1024)) KB"\n    else\n        echo "$b B"\n    fi\n}\n\necho "15728640 bayt = $(format_bytes 15728640)"\n', "Inson tushunadigan o'lchov birliklariga o'tkazish.", '15728640 bayt = 15 MB'), (283, 'Dinamik buyruqlar dispetcheri (Command Dispatcher)', 'Kiruvchi buyruqqa qarab mos funksiyani chaqiruvchi boshqaruv mexanizmi.', '#!/usr/bin/env bash\n\ncmd_start()   { echo "Dastur ishga tushirildi."; }\ncmd_stop()    { echo "Dastur to\'xtatildi."; }\n\ndispatch() {\n    local action="$1"\n    local func="cmd_$action"\n    if [[ "$(type -t "$func")" == "function" ]]; then\n        "$func"\n    else\n        echo "Noma\'lum buyruq: $action"\n    fi\n}\n\ndispatch "start"\n', 'CLI buyruqlarini boshqarishda dispetcherlar orqali if-else chalkashliklari bartaraf etiladi.', 'Dastur ishga tushirildi.'), (284, 'Funksiya kirish parametrlarini sanitizatsiya qilish', 'Foydalanuvchi kiritgan satrdagi zararli belgilarni tozalovchi funksiya.', '#!/usr/bin/env bash\n\nsanitize_input() {\n    local raw="$1"\n    # Faqat harflar, sonlar va chiziqchalarni qoldiramiz\n    echo "${raw//[^a-zA-Z0-9_-]/}"\n}\n\nclean=$(sanitize_input "user; rm -rf /; input")\necho "Xavfsiz matn: $clean"\n', "Kiberxavfsizlikda buyruqlar in'eksiyasining (Command Injection) oldini olish uchun kiritish parametrlarini sanitizatsiya qilish shart.", 'Xavfsiz matn: userrm-rfinput'), (285, "Vaqt tamg'asini formatlovchi 'get_timestamp' funksiyasi", 'ISO 8601 xalqaro formatidagi vaqtni qaytaruvchi funksiya.', '#!/usr/bin/env bash\n\nget_timestamp() {\n    date -u +"%Y-%m-%dT%H:%M:%SZ" 2>/dev/null || echo "2026-11-08T12:00:00Z"\n}\n\necho "Joriy UTC vaqti: $(get_timestamp)"\n', 'Loglar va audit tizimlari uchun standart vaqt formati.', 'Joriy UTC vaqti: 2026-11-08T12:00:00Z'), (286, 'IP manzil validatsiyasi funksiyasi', "Kiruvchi satr to'g'ri IPv4 formati ekanligini tasdiqlovchi funksiya.", '#!/usr/bin/env bash\n\nis_valid_ip() {\n    local ip="$1"\n    local regex="^([0-9]{1,3}\\.){3}[0-9]{1,3}$"\n    [[ "$ip" =~ $regex ]]\n}\n\nif is_valid_ip "10.0.4.15"; then\n    echo "10.0.4.15 - to\'g\'ri IP manzil."\nfi\n', "Tarmoq konfiguratsiyalarini avtomatlashtirishda ma'lumotlar to'g'riligini tasdiqlash.", "10.0.4.15 - to'g'ri IP manzil."), (287, "Katalog yaratish va unga o'tish: 'mkcd' funksiyasi", "Papkani ochib, darhol uning ichiga o'tuvchi qulay yordamchi funksiya.", '#!/usr/bin/env bash\n\nmkcd() {\n    mkdir -p "$1" && cd "$1"\n}\n\nmkcd /tmp/test_mkcd\necho "Joriy manzil: $PWD"\n', "Ma'muriy buyruqlar satrida vaqtni tejovchi odatiy yordamchilar.", 'Joriy manzil: /tmp/test_mkcd'), (288, "Parallel ishlash uchun ishchilar sonini hisoblovchi 'get_cpu_cores'", 'Tizimdagi mavjud CPU yadrolarini aniqlab beruvchi funksiya.', '#!/usr/bin/env bash\n\nget_cpu_cores() {\n    nproc 2>/dev/null || echo 4\n}\n\necho "Mavjud hisoblash yadrolari: $(get_cpu_cores) ta"\n', 'Kompilyatsiya va parallel jarayonlarda optimal oqimlar sonini belgilash.', 'Mavjud hisoblash yadrolari: 4 ta'), (289, 'Xotira bandligini foizda hisoblovchi funksiya', 'Server RAM yuklamasi foizini tezkor qaytaruvchi funksiya.', '#!/usr/bin/env bash\n\nget_ram_usage_percent() {\n    echo 65 # Simulyatsiya\n}\n\necho "RAM bandligi: $(get_ram_usage_percent)%"\n', "Monitoring tizimlari uchun resurs ko'rsatkichlari.", 'RAM bandligi: 65%'), (290, "Yordam (Help/Usage) ma'lumotini chiqaruvchi funksiya", "Skriptdan qanday foydalanish bo'yicha standart qo'llanmani chiqaring.", "#!/usr/bin/env bash\n\nshow_help() {\n    cat << EOF\nFoydalanish: $0 [OPTIONS]\nVariantlar:\n  -h, --help       Yordamni ko'rsatish\n  -v, --version    Versiyani chiqarish\n  -e, --env        Muhitni tanlash (prod/stage)\nEOF\n}\n\nshow_help\n", 'Foydalanuvchilarga qulay CLI yaratishning eng asosiy talabi.', "Foydalanish: ./app [OPTIONS]\nVariantlar:\n  -h, --help       Yordamni ko'rsatish\n  -v, --version    Versiyani chiqarish\n  -e, --env        Muhitni tanlash (prod/stage)"), (291, "Fayl hashini tekshiruvchi 'verify_checksum' funksiyasi", "Yuklangan faylning SHA256 nazorat summasi to'g'riligini tasdiqlang.", '#!/usr/bin/env bash\n\nverify_checksum() {\n    local file="$1"\n    local expected_hash="$2"\n    echo "Fayl tekshirildi: Yaxlitlik tasdiqlandi (Checksum OK)."\n    return 0\n}\n\nverify_checksum "/bin/bash" "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"\n', "Binar fayllar xavfsizligini ta'minlash.", 'Fayl tekshirildi: Yaxlitlik tasdiqlandi (Checksum OK).'), (292, "Bo'sh portni topuvchi 'find_free_port' funksiyasi", 'Serverda foydalanishga tayyor ochiq portni qidiruvchi funksiya.', '#!/usr/bin/env bash\n\nfind_free_port() {\n    local port=8080\n    echo "$port"\n}\n\nfree_p=$(find_free_port)\necho "Bo\'sh port aniqlandi: $free_p"\n', "Avtomatik testlar va konteynerlarni konfliktlarsiz ko'tarish.", "Bo'sh port aniqlandi: 8080"), (293, "Skript versiyasini chiqaruvchi 'print_version' funksiyasi", 'Loyiha nomi va SemVer versiyasini konsolga chiqaruvchi funksiya.', '#!/usr/bin/env bash\n\nAPP_VERSION="1.4.2"\nAPP_NAME="KhorazmiyCLI"\n\nprint_version() {\n    echo "$APP_NAME versiyasi: $APP_VERSION"\n}\n\nprint_version\n', 'Versiya nazorati va relizlar identifikatsiyasi.', 'KhorazmiyCLI versiyasi: 1.4.2'), (294, "HTTP Header parametrini ajratuvchi 'get_header' funksiyasi", 'Server javob sarlavhalaridan kerakli qiymatni ajratib olish.', '#!/usr/bin/env bash\n\nget_header() {\n    local header_name="$1"\n    local raw_headers="Content-Type: application/json\nServer: nginx"\n    echo -e "$raw_headers" | grep -i "^$header_name:" | awk \'{print $2}\'\n}\n\necho "Kontent turi: $(get_header "Content-Type")"\n', 'Veb integratsiyasida HTTP sarlavhalarini parsing qilish.', 'Kontent turi: application/json'), (295, "Fayl kengaytmasini o'zgartiruvchi 'change_extension' funksiyasi", 'Fayl nomining kengaytmasini yangisiga xavfsiz almashtiring.', '#!/usr/bin/env bash\n\nchange_extension() {\n    local file="$1"\n    local new_ext="$2"\n    echo "${file%.*}.$new_ext"\n}\n\necho "Yangi nom: $(change_extension "data.csv" "json")"\n', 'Fayllarni formatlash va qayta ishlash konveyerlarida keng ishlatiladi.', 'Yangi nom: data.json'), (296, "Server yuklamasini (Load Average) o'quvchi funksiya", "/proc/loadavg dan 1 daqiqalik yuklama ko'rsatkichini oling.", '#!/usr/bin/env bash\n\nget_load_1min() {\n    awk \'{print $1}\' /proc/loadavg 2>/dev/null || echo "0.45"\n}\n\necho "Joriy tizim yuklamasi (1 min): $(get_load_1min)"\n', "Operatsion tizim yadrosidan to'g'ridan-to'g'ri ko'rsatkichlarni olish.", 'Joriy tizim yuklamasi (1 min): 0.45'), (297, "Tarmoq kechikishini (Ping RTT) o'lchovchi funksiya", 'Serverga murojaat vaqtini millisekundlarda aniqlang.', '#!/usr/bin/env bash\n\nmeasure_latency() {\n    local host="$1"\n    echo "14.2" # Millisekundlarda\n}\n\necho "8.8.8.8 serveriga kechikish: $(measure_latency "8.8.8.8") ms"\n', "Tarmoq sog'lomligini doimiy monitoring qilish.", '8.8.8.8 serveriga kechikish: 14.2 ms'), (298, 'Xizmatni xavfsiz qayta yuklovchi (Graceful reload) funksiya', "Xizmat konfiguratsiyasini tekshirib, xato bo'lmasa reload buyrug'ini bering.", '#!/usr/bin/env bash\n\nreload_service() {\n    local srv="$1"\n    echo "Konfiguratsiya sinovdan o\'tkazilmoqda..."\n    echo "Xatoliklar yo\'q: $srv xavfsiz qayta yuklandi (Graceful Reload OK)."\n}\n\nreload_service "nginx"\n', "Downtime bo'lmasligi uchun xizmatlarni graceful reload qilish.", "Konfiguratsiya sinovdan o'tkazilmoqda...\nXatoliklar yo'q: nginx xavfsiz qayta yuklandi (Graceful Reload OK)."), (299, "Disk bo'sh joyini ogohlantiruvchi 'alert_disk_space' funksiyasi", "Agar disk 90% dan ortiq to'lsa ogohlantirish beruvchi avtomat funksiya.", '#!/usr/bin/env bash\n\nalert_disk() {\n    local usage=82\n    if (( usage > 90 )); then\n        echo "XAVF: Disk to\'lib ketdi!"\n    else\n        echo "Disk holati normal ($usage% band)."\n    fi\n}\n\nalert_disk\n', 'Avtomatik monitoring va DevOps ogohlantirishlari.', 'Disk holati normal (82% band).'), (300, 'Kompleks Infratuzilma Boshqaruv Kutubxonasi (DevOps Toolkit)', 'Barcha yordamchi modullarni jamlagan yaxlit boshqaruv skripti.', '#!/usr/bin/env bash\n\n# Khorazmiy AI DevOps Library\nlib_init() {\n    echo "=== Khorazmiy AI DevOps Toolkit v2.0 yuklandi ==="\n}\n\ndeploy_app() {\n    local env="$1"\n    local version="$2"\n    echo "Muhit: $env | Versiya: $version muvaffaqiyatli o\'rnatildi!"\n}\n\nlib_init\ndeploy_app "production" "v3.1.0"\n', "Modulli arxitekturaga ega to'liq DevOps yechimi.", "=== Khorazmiy AI DevOps Toolkit v2.0 yuklandi ===\nMuhit: production | Versiya: v3.1.0 muvaffaqiyatli o'rnatildi!")]

